package adminresources

import (
	"context"
	"cosmicforge/logistics/shared/go/adminowner"
	"github.com/jackc/pgx/v5/pgxpool"
)

const Owner = "fleet-partner-service"

func Source() *adminowner.SQLSource {
	return adminowner.NewSQLSource(Owner, map[string]adminowner.SQLSpec{
		"organizations":          {Table: "fleet_partner_organizations", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"id"}, Dimensions: map[string]string{"country": "country_code", "currency": "default_currency", "timezone": "timezone"}},
		"onboarding-stages":      {Table: "fleet_partner_organization_onboarding_stages", ReferenceExpression: "t.organization_id || ':' || t.stage", CreatedAtExpression: "t.updated_at", UpdatedAtExpression: "t.updated_at", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "stage"}, Dimensions: map[string]string{"stage": "stage"}, References: map[string]string{"organization": "organization_id"}},
		"organization-documents": {Table: "fleet_partner_organization_documents", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "document_type", "file_id"}, Dimensions: map[string]string{"document_type": "document_type", "expires_at": "expires_at"}, Counters: map[string]string{"verification_source_version": "source_version"}, References: map[string]string{"organization": "organization_id", "media_object": "file_id", "verification": "verification_reference"}},
		"branches":               {Table: "fleet_partner_branches", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id"}, Dimensions: map[string]string{"branch_type": "type", "timezone": "timezone", "geofence": "geofence_reference"}, References: map[string]string{"organization": "organization_id"}},
		"departments":            {Table: "fleet_partner_departments", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "branch_id", "parent_id"}, Dimensions: map[string]string{"cost_centre": "cost_centre_id"}, References: map[string]string{"organization": "organization_id", "branch": "branch_id", "parent_department": "parent_id"}},
		"organization-staff":     {Table: "fleet_partner_organization_users", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id"}, Dimensions: map[string]string{"job_title": "job_title"}, Counters: map[string]string{"role_version": "role_version"}, References: map[string]string{"organization": "organization_id"}},
		"role-bindings":          {Table: "(SELECT rb.*, CASE WHEN rb.revoked_at IS NOT NULL THEN 'REVOKED' WHEN rb.expires_at IS NOT NULL AND rb.expires_at <= now() THEN 'EXPIRED' WHEN rb.effective_from > now() THEN 'SCHEDULED' ELSE 'ACTIVE' END AS effective_state FROM fleet_partner_role_bindings rb)", VersionColumn: "version", StateColumn: "effective_state", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "organization_user_id", "role_id", "scope_type", "scope_id"}, Dimensions: map[string]string{"scope_type": "scope_type", "effective_state": "effective_state"}, References: map[string]string{"organization": "organization_id", "organization_staff": "organization_user_id", "role": "role_id", "scope": "scope_id"}},
		"provider-memberships":   {Table: "fleet_partner_organization_provider_memberships", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "provider_service", "provider_id", "home_branch_id"}, Dimensions: map[string]string{"service_type": "provider_service", "provider_category": "service_category", "relationship_type": "relationship_type", "onboarding_source": "onboarding_source"}, References: map[string]string{"organization": "organization_id", "home_branch": "home_branch_id", "provider": "provider_id"}},
		"assets":                 {Table: "fleet_partner_assets", VersionColumn: "version", StateColumn: "operational_status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "branch_id", "platform_vehicle_id"}, Dimensions: map[string]string{"asset_type": "asset_type", "ownership_type": "ownership_type", "lifecycle": "lifecycle_status", "assignment_active": ""}, DimensionQuery: "SELECT jsonb_build_object('assignment_active', EXISTS(SELECT 1 FROM fleet_partner_asset_assignments a WHERE a.asset_id=$1 AND a.status='ACTIVE'))", References: map[string]string{"organization": "organization_id", "branch": "branch_id", "platform_vehicle": "platform_vehicle_id"}},
		"asset-assignments":      {Table: "fleet_partner_asset_assignments", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "asset_id", "provider_membership_id", "shift_id"}, Dimensions: map[string]string{"assignment_type": "assignment_type", "start_at": "start_at", "end_at": "end_at"}, References: map[string]string{"organization": "organization_id", "asset": "asset_id", "provider_membership": "provider_membership_id", "shift": "shift_id"}},
		"asset-documents":        {Table: "fleet_partner_asset_documents", VersionColumn: "version", StateColumn: "verification_status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "asset_id", "media_file_id"}, Dimensions: map[string]string{"document_type": "document_type", "expires_at": "expires_at"}, References: map[string]string{"organization": "organization_id", "asset": "asset_id", "media_object": "media_file_id", "verification": "verification_reference"}},
		"contracts":              {Table: "fleet_partner_contracts", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "branch_id", "customer_id", "quotation_id"}, Dimensions: map[string]string{"effective_from": "effective_from", "effective_until": "effective_to", "currency": ""}, DimensionQuery: "SELECT COALESCE((SELECT jsonb_build_object('currency', q.currency) FROM fleet_partner_contracts c LEFT JOIN fleet_partner_quotations q ON q.id=c.quotation_id WHERE c.id=$1), '{}'::jsonb)", References: map[string]string{"organization": "organization_id", "branch": "branch_id", "customer": "customer_id", "quotation": "quotation_id"}},
		"crm-contacts":           {Table: "fleet_partner_customer_contacts", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "customer_id"}, Dimensions: map[string]string{"preferred_channel": "preferred_channel", "contact_purpose": "contact_purpose", "consent": "consent_status"}, References: map[string]string{"organization": "organization_id", "customer": "customer_id"}},
		"quotations":             {Table: "fleet_partner_quotations", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "branch_id", "customer_id", "opportunity_id"}, Dimensions: map[string]string{"currency": "currency", "valid_until": "valid_until"}, Counters: map[string]string{"current_version": "current_version", "total_amount_minor": "total_amount_minor"}, References: map[string]string{"organization": "organization_id", "branch": "branch_id", "customer": "customer_id", "opportunity": "opportunity_id", "contract_approval": "approval_request_id"}},
		"approval-requests":      {Table: "fleet_partner_approval_requests", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "policy_id", "resource_type", "resource_id"}, Dimensions: map[string]string{"resource_type": "resource_type", "action": "action", "expires_at": "expires_at"}, Counters: map[string]string{"current_step": "current_step"}, References: map[string]string{"organization": "organization_id", "policy": "policy_id", "resource": "resource_id"}},
		"wallet-transactions":    {Table: "fleet_partner_wallet_transaction_projections", VersionColumn: "version", StateColumn: "safe_status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "branch_id", "wallet_reference", "transaction_reference", "subject_type", "subject_id"}, Dimensions: map[string]string{"direction": "direction", "category": "category", "currency": "currency", "freshness": "freshness_state"}, Counters: map[string]string{"amount_minor": "amount_minor", "source_version": "source_version"}, References: map[string]string{"organization": "organization_id", "branch": "branch_id", "wallet": "wallet_reference", "transaction": "transaction_reference", "subject": "subject_id"}},
		"private-orders":         {Table: "fleet_partner_private_orders", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "branch_id", "customer_id", "contract_id", "quotation_id"}, Dimensions: map[string]string{"source": "source", "priority": "priority", "timezone": "timezone"}, References: map[string]string{"organization": "organization_id", "branch": "branch_id", "customer": "customer_id", "contract": "contract_id", "quotation": "quotation_id"}},
		"recurring-orders":       {Table: "fleet_partner_recurring_order_templates", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "branch_id", "customer_id", "contract_id"}, Dimensions: map[string]string{"recurrence_type": "recurrence_type", "timezone": "timezone", "next_run_at": "next_run_at", "missed_run_policy": "missed_run_policy"}, Counters: map[string]string{"attempts": "attempts"}, References: map[string]string{"organization": "organization_id", "branch": "branch_id", "customer": "customer_id", "contract": "contract_id"}},
		"manifests":              {Table: "fleet_partner_manifests", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "branch_id", "future_route_plan_id", "provider_membership_id"}, Dimensions: map[string]string{"route_reference": "route_reference"}, References: map[string]string{"organization": "organization_id", "branch": "branch_id", "provider_membership": "provider_membership_id", "route_plan": "future_route_plan_id"}},
		"route-plans":            {Table: "fleet_partner_route_plans", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "branch_id", "dispatch_plan_id", "provider_membership_id"}, Dimensions: map[string]string{"route_type": "route_type", "execution_service": "execution_service", "distance_unit": "distance_unit"}, Counters: map[string]string{"planned_duration_seconds": "planned_duration_seconds", "optimization_version": "optimization_version"}, References: map[string]string{"organization": "organization_id", "branch": "branch_id", "dispatch_plan": "dispatch_plan_id", "replacement_route": "replacement_for_route_id", "provider_membership": "provider_membership_id"}},
		"route-optimizations":    {Table: "fleet_partner_route_optimization_requests", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "route_plan_id", "route_version", "optimization_version"}, Dimensions: map[string]string{"provider_reference": "provider_reference"}, Counters: map[string]string{"route_version": "route_version", "optimization_version": "optimization_version", "result_version": "result_version", "estimated_duration_seconds": "estimated_duration_seconds"}, References: map[string]string{"organization": "organization_id", "route_plan": "route_plan_id"}},
		"operational-alerts":     {Table: "fleet_partner_operational_alerts", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "branch_id", "source_type", "source_id", "route_plan_id", "assignment_id", "shipment_id"}, Dimensions: map[string]string{"alert_type": "alert_type", "severity": "severity", "source_type": "source_type", "sla_due_at": "sla_due_at"}, References: map[string]string{"organization": "organization_id", "branch": "branch_id", "source": "source_id", "route_plan": "route_plan_id", "assignment": "assignment_id", "shipment": "shipment_id"}},
		"incidents":              {Table: "fleet_partner_incidents", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "branch_id", "route_id", "assignment_id", "trip_reference"}, Dimensions: map[string]string{"incident_type": "incident_type", "severity": "severity", "occurred_at": "occurred_at"}, References: map[string]string{"organization": "organization_id", "branch": "branch_id", "route": "route_id", "assignment": "assignment_id", "trip": "trip_reference"}},
		"sla-measurements":       {Table: "fleet_partner_sla_measurements", CreatedAtExpression: "t.generated_at", UpdatedAtExpression: "t.generated_at", VersionColumn: "version", StateColumn: "breach_status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "agreement_reference", "contract_id", "customer_id", "formula_version", "period_start", "period_end"}, Dimensions: map[string]string{"metric_code": "metric_code", "unit": "unit", "target": "", "measured": "", "period_start": "period_start", "period_end": "period_end"}, DimensionQuery: "SELECT COALESCE((SELECT jsonb_build_object('target', m.target_value::text, 'measured', m.measured_value::text) FROM fleet_partner_sla_measurements m WHERE m.id=$1), '{}'::jsonb)", Counters: map[string]string{"formula_version": "formula_version"}, References: map[string]string{"organization": "organization_id", "contract": "contract_id", "customer": "customer_id", "agreement": "agreement_reference"}},
		"audit-records":          {Table: "fleet_partner_audit_records", CreatedAtExpression: "t.occurred_at", UpdatedAtExpression: "t.occurred_at", StateColumn: "", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "branch_id", "resource_type", "resource_id"}, Dimensions: map[string]string{"action": "action", "resource_type": "resource_type"}, References: map[string]string{"organization": "organization_id", "resource": "resource_id"}},
		"shipments":              {Table: "fleet_partner_shipments", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "order_id"}, Dimensions: map[string]string{"planning": "status", "custody": "", "return": ""}, References: map[string]string{"order": "order_id", "branch": "branch_id"}},
		"private-assignments":    {Table: "fleet_partner_private_assignments", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "private_order_id", "shipment_id", "work_origin"}, Dimensions: map[string]string{"execution_service": "execution_service", "work_origin": "work_origin"}, References: map[string]string{"provider": "provider_id", "vehicle": "vehicle_or_truck_reference", "shipment": "shipment_id", "order": "private_order_id"}},
		// Fleet-owned standalone investigations. Status is the case state; the
		// organization is the one copied from the subject's authoritative row.
		"investigations":  {Table: "fleet_partner_admin_investigations", ReferenceExpression: "t.case_ref", VersionColumn: "version", StateColumn: "state", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "subject_kind", "subject_id"}, Dimensions: map[string]string{"subject_kind": "subject_kind", "category": "category", "severity": "severity", "occurred_on": "occurred_on", "finding": "finding", "closure": "closure"}, References: map[string]string{"organization": "organization_id", "shipment": "shipment_id", "private_assignment": "private_assignment_id", "execution_link": "execution_link_id", "organization_subject": "organization_subject_id", "asset": "asset_id", "contract": "contract_id", "incident": "incident_id", "route_plan": "route_plan_id", "route_optimization": "route_optimization_id", "sla_measurement": "sla_measurement_id"}},
		"execution-links": {Table: "fleet_partner_private_execution_operations", VersionColumn: "version", StateColumn: "status", OrganizationColumn: "organization_id", CanonicalTenantIsOrganization: true, BindingColumns: []string{"organization_id", "private_order_id", "shipment_id", "assignment_id"}, Dimensions: map[string]string{"execution_service": "execution_service"}, References: map[string]string{"provider": "executing_provider_id", "vehicle": "vehicle_or_truck_reference", "shipment": "shipment_id", "assignment": "assignment_id", "response": "provider_response_id", "canonical_mission": "canonical_trip_reference"}},
	})
}
func Runtime(ctx context.Context, db *pgxpool.Pool) (*adminowner.Handler, error) {
	profile, _ := adminowner.ForOwner(Owner)
	return adminowner.FromEnvironment(ctx, db, Source(), profile.Definitions, Owner, profile.Prefix, profile.Path)
}
